          "correctAnswer": 3,
          "explanation": "<b>傷む（いたむ）：</b>Hư tổn, xơ rối (tóc, móng tay); ôi thiu hỏng hóc (thực phẩm, hoa quả).<br><b>Dịch nghĩa:</b> Hễ cứ nhuộm tóc hay uốn tóc là sợi tóc lại bị hư tổn, xơ rối.<br><i>Phân tích các phương án:</i><br>• 1. くさる (腐る): Thối rữa, ôi thiu hỏng do vi khuẩn (dùng cho thức ăn)<br>• 2. さびる (錆びる): Rỉ sét, hoen gỉ (dùng cho kim loại sắt thép)<br>• <b>3. いたむ (傷む): Bị hư tổn, xơ xác, hư hại [Đúng]</b><br>• 4. おとる (劣る): Kém cỏi hơn, thua kém về năng lực hoặc chất lượng"
