          "correctAnswer": 1,
          "explanation": "<b>効く（きく）：</b>Có tác dụng, hiệu nghiệm, phát huy hiệu quả (dùng cho thuốc men, biện pháp). Đi với cụm: 薬が効く.<br><b>Dịch nghĩa:</b> Có lẽ là nhờ thuốc đã phát huy tác dụng mà cơn sốt của tôi đã hạ hẳn.<br><i>Phân tích các phương án:</i><br>• <b>1. 効いた (きいた): Phát huy tác dụng, ngấm thuốc [Đúng]</b><br>• 2. そまった (染まった): Bị nhuộm màu, bị tiêm nhiễm thói xấu<br>• 3. つき抜けて (突き抜けて): Đâm thủng qua, xuyên qua<br>• 4. わいた (沸いた): Sôi lên (nước sôi, không khí sôi sục)"
